TABS.push(['governance','版本治理']);
var candidateDrawTab=drawTab;
drawTab=function(){if(state.tab!=='governance')return candidateDrawTab();renderGovernanceTab()};
var GOVERNANCE_STATUS_LABELS={draft:'草稿',reviewed:'已审核',approved:'已批准',published:'已发布'};
function governanceStatusTag(value){var cls=value==='published'?'ok':value==='approved'?'info':value==='reviewed'?'info':'off';return '<span class="tag '+cls+'">'+esc(GOVERNANCE_STATUS_LABELS[value]||value||'—')+'</span>'}
function governanceVersionActions(item){if(item.status==='draft')return '<button class="btn btn-sm" onclick="openVersionAction(\'review\',\''+esc(item.version)+'\')">提交审核</button>';if(item.status==='reviewed')return '<button class="btn btn-sm" onclick="openVersionAction(\'approve\',\''+esc(item.version)+'\')">确认批准</button>';if(item.status==='approved')return '<button class="btn btn-primary btn-sm" onclick="openVersionAction(\'publish\',\''+esc(item.version)+'\')">发布版本</button>';if(item.status==='published'&&!item.is_active)return '<button class="btn btn-sm" onclick="openVersionAction(\'rollback\',\''+esc(item.version)+'\')">回滚至此版本</button>';return '<span class="governance-current-note">'+(item.is_active?'当前生效中':'流程已完成')+'</span>'}
function governanceStageRail(status){var order=['draft','reviewed','approved','published'],current=order.indexOf(status);return '<div class="governance-mini-rail">'+order.map(function(stage,index){return '<i class="'+(index<=current?'done':'')+'" title="'+esc(GOVERNANCE_STATUS_LABELS[stage])+'"></i>'}).join('')+'</div>'}
