function governanceEventRow(item){var label=item.action==='rollback'?'版本回滚':'版本发布',transition=(item.from_version?'v'+item.from_version:'首次发布')+' → v'+(item.to_version||'—');return '<div><i class="'+(item.action==='rollback'?'rollback':'')+'"></i><span><b>'+esc(label)+'</b><small>'+esc(transition)+' · '+esc(formatRuntimeTime(item.created_at))+'</small></span></div>'}
function renderGovernanceTab(){var tb=document.getElementById('tab-body');if(!tb)return;tb.innerHTML='<div class="governance-hero"><div><div class="workflow-kicker">ONTOLOGY RELEASE CONTROL</div><h3>版本治理</h3><p>将当前本体框架保存为不可变发布候选，按草稿、审核、批准、发布顺序受控切换。</p></div><button class="btn btn-sm" onclick="loadGovernance()">刷新状态</button></div><div class="governance-stage-rail"><div class="done"><i>1</i><span><b>草稿</b><small>保存候选内容</small></span></div><em></em><div><i>2</i><span><b>审核</b><small>数据与公理门禁</small></span></div><em></em><div><i>3</i><span><b>批准</b><small>锁定审核摘要</small></span></div><em></em><div><i>4</i><span><b>发布</b><small>切换 TBox / ABox</small></span></div></div><div id="governance-summary" class="governance-summary"></div><div class="governance-layout"><main><section class="card governance-card"><div class="governance-card-head"><div><h4>创建版本草稿</h4><p>以当前建模工作台内容生成新的 SemVer 版本</p></div><span class="tag off">不会直接发布</span></div><div class="governance-draft-grid"><div class="workflow-control"><label for="gov-version">新版本号</label><input id="gov-version" placeholder="例如 1.2.0" autocomplete="off"></div><div class="workflow-control grow"><label for="gov-note">变更说明</label><input id="gov-note" placeholder="说明业务变化、兼容性与发布目的"></div><button id="gov-draft-button" class="btn btn-primary" onclick="saveDraftVersion()">保存草稿</button></div></section><section class="card governance-card"><div class="governance-card-head"><div><h4>版本记录</h4><p>操作入口跟随每个版本的实际状态显示</p></div></div><div id="gov-versions"><div class="workflow-empty-list">正在读取版本记录…</div></div></section></main><aside><section class="card governance-card"><div class="governance-card-head"><div><h4>本体 Git</h4><p>提交不可变快照，管理协作分支和标签</p></div><span id="git-head-label" class="tag info">读取中</span></div><div class="governance-git-fields"><div class="workflow-control"><label for="git-branch">工作分支</label><select id="git-branch" onchange="loadGovernance()"><option value="main">main</option></select></div><div class="workflow-control"><label for="git-author">提交人</label><input id="git-author" placeholder="姓名或工号"></div><div class="workflow-control full"><label for="git-message">提交说明</label><input id="git-message" placeholder="至少 3 个字符"></div><button class="btn btn-primary full" onclick="commitOntologySnapshot()">提交当前本体快照</button></div><div class="governance-git-create"><div><input id="git-new-branch" placeholder="新分支名称"><button class="btn btn-sm" onclick="createOntologyBranch()">创建分支</button></div><div><input id="git-new-tag" placeholder="标签，例如 v1.2.0"><button class="btn btn-sm" onclick="createOntologyTag()">创建标签</button></div></div></section><section class="card governance-card"><div class="governance-card-head"><div><h4>最近提交</h4><p>当前分支的不可变历史</p></div></div><div id="gov-git"><div class="workflow-empty-list">正在读取提交历史…</div></div></section><section class="card governance-card"><div class="governance-card-head"><div><h4>发布动态</h4><p>仅展示生效版本的切换记录</p></div></div><div id="gov-events"><div class="workflow-empty-list">正在读取发布动态…</div></div></section><section class="governance-boundary"><b>发布与回滚边界</b><p>发布或回滚前都会重新执行数据质量、公理、ABox 兼容性和映射校验；失败时保留当前活动版本。</p></section></aside></div>';loadGovernance()}
window.loadGovernance=async function(){try{var requestedBranch=(document.getElementById('git-branch')&&document.getElementById('git-branch').value)||'main',values=await Promise.all([api('/ontology/versions'),api('/ontology/git/status'),api('/ontology/version-events?limit=20')]),versionData=values[0],versions=versionData.versions||[],status=values[1],events=values[2].events||[],branches=status.branches||[],branch=branches.some(function(item){return item.name===requestedBranch})?requestedBranch:(status.default_branch||'main'),log=await api('/ontology/git/log?ref='+encodeURIComponent(branch)+'&limit=12'),active=versionData.active_version||'—',drafts=versions.filter(function(item){return item.status==='draft'}).length,approved=versions.filter(function(item){return item.status==='approved'}).length;gitHead=(branches.find(function(item){return item.name===branch})||{}).head_commit_id||null;var summary=document.getElementById('governance-summary');if(summary)summary.innerHTML='<div><span>当前活动版本</span><b>v'+esc(active)+'</b></div><div><span>版本总数</span><b>'+versions.length+'</b></div><div><span>待审核草稿</span><b>'+drafts+'</b></div><div><span>待发布版本</span><b>'+approved+'</b></div>';var versionEl=document.getElementById('gov-versions');if(versionEl)versionEl.innerHTML=versions.length?versions.map(governanceVersionRow).join(''):'<div class="workflow-empty-list">暂无版本记录</div>';var branchSelect=document.getElementById('git-branch');if(branchSelect)branchSelect.innerHTML=branches.map(function(item){return '<option value="'+esc(item.name)+'"'+(item.name===branch?' selected':'')+'>'+esc(item.name)+(item.is_default?'（默认）':'')+'</option>'}).join('');var headLabel=document.getElementById('git-head-label');if(headLabel)headLabel.textContent=gitHead?String(gitHead).slice(0,8):'空分支';var gitEl=document.getElementById('gov-git'),commits=log.commits||[];if(gitEl)gitEl.innerHTML=commits.length?'<div class="governance-commit-list">'+commits.map(function(item){return '<div><code>'+esc(String(item.commit_id||'').slice(0,8))+'</code><span><b>'+esc(item.message)+'</b><small>'+esc(item.author)+' · '+esc(formatRuntimeTime(item.created_at))+'</small></span></div>'}).join('')+'</div>':'<div class="workflow-empty-list">当前分支暂无提交</div>';var eventEl=document.getElementById('gov-events');if(eventEl)eventEl.innerHTML=events.length?'<div class="governance-event-list">'+events.map(governanceEventRow).join('')+'</div>':'<div class="workflow-empty-list">尚无发布或回滚记录</div>'}catch(e){toast(e.message,'err')}};
window.saveDraftVersion=async function(){var button=document.getElementById('gov-draft-button');try{var version=document.getElementById('gov-version').value.trim(),notes=document.getElementById('gov-note').value.trim();if(!/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(version))throw new Error('版本号需使用 SemVer，例如 1.2.0');if(!notes)throw new Error('请填写本次版本的变更说明');if(button){button.disabled=true;button.textContent='正在保存…'}var proposal=ontologyToProposal(curOnt());proposal.version=version;var data=await api('/ontology/versions/drafts',{method:'POST',body:body({proposal:proposal,notes:notes})});liveProposal=data.proposal||proposal;curOnt().version=version;toast('草稿 v'+version+' 已保存','ok');loadGovernance()}catch(e){toast(e.message,'err')}finally{if(button){button.disabled=false;button.textContent='保存草稿'}}};
window.openVersionAction=function(action,version){var titles={review:'提交审核',approve:'确认批准',publish:'发布版本',rollback:'回滚版本'},descriptions={review:'将执行结构、字段、公理和能力边界审核。',approve:'批准后内容与审核摘要将被锁定。',publish:'将安全切换 TBox 并同步 ABox，失败时自动保留当前版本。',rollback:'仅可回滚到曾成功发布的版本，并会重新执行全部门禁。'},needsNote=action==='review'||action==='approve';openModal(mHead((titles[action]||action)+' · v'+version,descriptions[action]||'受控版本操作')+'<div class="modal-body frm">'+(needsNote?'<label for="gov-transition-note">处理说明</label><textarea id="gov-transition-note" placeholder="记录本次'+(titles[action]||action)+'的依据"></textarea>':'<div class="governance-confirm"><b>请确认目标版本：v'+esc(version)+'</b><p>'+esc(descriptions[action]||'')+'</p></div>')+(action==='rollback'?'<div class="warnbox">回滚不会删除后续版本记录，只切换当前活动版本。</div>':'')+'</div><div class="modal-foot"><button class="btn" onclick="closeModal()">取消</button><button id="gov-transition-button" class="btn '+(action==='publish'?'btn-primary':'')+'" onclick="versionAction(\''+esc(action)+'\',\''+esc(version)+'\')">确认'+esc(titles[action]||action)+'</button></div>',620)};
window.versionAction=async function(action,version){var button=document.getElementById('gov-transition-button');try{var options={method:'POST'},note=document.getElementById('gov-transition-note');if(action==='review'||action==='approve')options.body=body({note:(note&&note.value||'').trim()});if(button){button.disabled=true;button.textContent='正在处理…'}var result=await api('/ontology/versions/'+encodeURIComponent(version)+'/'+action,options);if(result.status==='review_failed'){closeModal();toast('版本审核未通过，共 '+Number(result.audit&&result.audit.summary&&result.audit.summary.failed||0)+' 项门禁失败','err');loadGovernance();return}if(action==='publish'||action==='rollback'){curOnt().status='published';curOnt().version=version}closeModal();toast('版本 v'+version+' 已完成'+({review:'审核',approve:'批准',publish:'发布',rollback:'回滚'}[action]||action),'ok');loadGovernance()}catch(e){toast(e.message,'err');if(button){button.disabled=false;button.textContent='重试'}}};
doPublish=async function(){var ontology=curOnt(),version=String(ontology.version);if(!confirm('发布版本 '+version+' 将切换 NebulaGraph TBox 并重新同步 ABox，是否继续？'))return;try{await api('/ontology/versions/'+encodeURIComponent(version)+'/publish',{method:'POST'});ontology.status='published';ontology.updatedAt=now();closeModal();renderModel();toast('版本 '+version+' 已发布到真实图谱','ok')}catch(e){toast(e.message,'err')}};
window.commitOntologySnapshot=async function(){try{var branch=document.getElementById('git-branch').value.trim()||'main',author=document.getElementById('git-author').value.trim(),message=document.getElementById('git-message').value.trim();if(!author||message.length<3)throw new Error('请填写提交人和至少3个字符的提交说明');await api('/ontology/git/commits',{method:'POST',body:body({branch:branch,proposal:ontologyToProposal(curOnt()),message:message,author:author,expected_head:gitHead})});document.getElementById('git-message').value='';toast('本体快照已提交','ok');loadGovernance()}catch(e){toast(e.message,'err')}};
window.createOntologyBranch=async function(){try{var input=document.getElementById('git-new-branch'),name=(input.value||'').trim(),fromRef=document.getElementById('git-branch').value||'main';if(!name)throw new Error('请填写新分支名称');await api('/ontology/git/branches',{method:'POST',body:body({name:name,from_ref:fromRef})});input.value='';toast('分支 '+name+' 已创建','ok');loadGovernance()}catch(e){toast(e.message,'err')}};
window.createOntologyTag=async function(){try{var input=document.getElementById('git-new-tag'),name=(input.value||'').trim(),ref=document.getElementById('git-branch').value||'main';if(!name)throw new Error('请填写标签名称');await api('/ontology/git/tags',{method:'POST',body:body({name:name,ref:ref,message:'由版本治理工作台创建'})});input.value='';toast('标签 '+name+' 已创建','ok');loadGovernance()}catch(e){toast(e.message,'err')}};

