esc(formatRuntimeTime(workflow.updated_at))+'</dd></div><div><dt>流程编号</dt><dd title="'+esc(workflow.workflow_id)+'">'+esc(String(workflow.workflow_id||'').slice(0,8))+'…</dd></div></dl></div><div class="workflow-side-card"><span class="workflow-side-label">最近动态</span><div class="workflow-event-list">'+(recent.length?recent.map(function(event){return '<div><i></i><span><b>'+esc(workflowEventLabel(event.event_type))+'</b><small>'+esc(formatRuntimeTime(event.created_at))+'</small></span></div>'}).join(''):'<p class="live-note">暂无流程动态</p>')+'</div></div><div class="workflow-side-card boundary"><b>决策安全边界</b><p>系统只汇总证据并记录建议；最终审批仍由有权业务系统完成。</p></div></aside></div>';
