function renderWorkflowFields(action){var definition=workflowActionDefinition(action),fields=definition.request_fields||[],html='',systemFields=[];fields.forEach(function(field){if(WORKFLOW_SYSTEM_FIELDS[field]){systemFields.push(field);return}if(WORKFLOW_GROUP_META[field])html+=renderWorkflowGroup(field);else if(field==='approval_assertion'){var assertion=workflowDefinition&&workflowDefinition.recommendation_only_assertion||'我确认该记录仅为决策建议，不代表最终审批';html+='<div class="workflow-approval"><label class="workflow-assertion"><input id="wf-approval-assertion" type="checkbox"> <span><b>人工确认</b>'+esc(assertion)+'</span></label></div>'}else html+=renderWorkflowField(field,field,!(WORKFLOW_FIELD_META[field]||{}).optional)});return (systemFields.length?'<div class="workflow-system-note">请求编号、回调编号和确认人身份由服务端根据当前流程自动写入，无需手工填写。</div>':'')+'<div class="workflow-form-grid">'+html+'</div>'}
