window.syncWorkflowConditionalFields=function(){var channel=document.querySelector('[data-workflow-field="application.channel"]'),status=document.querySelector('[data-workflow-field="application.application_status"]'),conclusion=document.querySelector('[data-workflow-field="conclusion"]'),dealer=document.querySelector('[data-workflow-group="dealer"]'),dealerToggle=dealer&&dealer.querySelector('.workflow-group-toggle input'),income=document.querySelector('[data-workflow-field="borrower.monthly_income"]'),incomeWrap=income&&income.closest('.workflow-field'),doubts=document.querySelector('[data-workflow-field="doubts"]'),doubtsWrap=doubts&&doubts.closest('.workflow-field');if(channel&&dealerToggle&&['线下门店','经销商APP'].indexOf(channel.value)>=0&&!dealerToggle.checked){dealerToggle.checked=true;toggleWorkflowGroup('dealer',true)}if(income){var incomeRequired=!!status&&status.value==='评估中';income.required=incomeRequired;if(incomeWrap){var labelEl=incomeWrap.querySelector('label');if(labelEl)labelEl.innerHTML='月收入'+(incomeRequired?' <b>*</b>':'')}}if(doubts){var doubtRequired=!!conclusion&&conclusion.value==='存疑';doubts.required=doubtRequired;if(doubtsWrap){var doubtsLabel=doubtsWrap.querySelector('label');if(doubtsLabel)doubtsLabel.innerHTML='疑点说明'+(doubtRequired?' <b>*</b>':'')}}};
function workflowFieldValue(path,required){var input=document.querySelector('[data-workflow-field="'+path+'"]');if(!input||input.disabled)return undefined;var raw=String(input.value||'').trim();if(!raw){if(required)throw new Error((input.previousElementSibling&&input.previousElementSibling.textContent||path).replace('*','').trim()+'不能为空');return undefined}var type=input.getAttribute('data-value-type');if(type==='integer'){var integer=Number(raw);if(!Number.isInteger(integer))throw new Error(path+' 必须是整数');return integer}if(type==='number'){var number=Number(raw);if(!Number.isFinite(number))throw new Error(path+' 必须是数值');return number}if(type==='datetime'){var date=new Date(raw);if(Number.isNaN(date.getTime()))throw new Error(path+' 必须是有效时间');return date.toISOString()}return raw}
